"""runtime.checks: generated by the graph.py split (P1)."""

from __future__ import annotations

import subprocess
from typing import Any

from ..runtime import observations, stage_services, tools
from ..runtime.policy import PolicyError
from ..runtime.tools import RepoToolbox
from ..state import CfuDesignState

#: Artifact stage -> the directory its persisted command logs live in.
_LOG_DIRS = {"validation": "10_validation/logs", "cost": "11_cost/logs",
             "profile": "05_profile/logs"}


def _run_check(
    state: CfuDesignState,
    toolbox: RepoToolbox,
    argv: list[str],
    *,
    rung: str,
    command_id: str = "",
    timeout: int = 3600,
    mutate: bool = False,
    log_stage: str = "",
) -> dict:
    """Run one ladder command, turning hard failures into a failed rung result.

    A hanging simulator (``TimeoutExpired``), a missing toolchain (``OSError``),
    or a command that the access policy does not allow must be a failing rung
    the ladder can repair, not an exception that kills the run.

    Every executed command's complete stdout/stderr is persisted under
    ``log_stage``'s directory (default: the validation/cost rung's own), so the
    run keeps a readable trace of what it built, simulated or synthesised.
    """
    result: dict[str, Any] | None = None
    if not command_id:
        # Resolve the declared command id here so an unallowlisted user command
        # (for example a custom C-project run_cmd) becomes a repairable failure
        # instead of a PolicyError escaping the graph.
        try:
            command_id = tools.infer_command_id(argv, toolbox.policy)
        except PolicyError as exc:
            result = {
                "command": " ".join(argv),
                "cwd": str(toolbox.workdir),
                "returncode": -2,
                "stdout_tail": "",
                "stderr_tail": f"command is not allowlisted for stage {toolbox.stage}: {exc}",
                "rung": rung,
                "parsed": {},
            }
            command_id = "policy_rejected"
    try:
        if result is not None:
            raise StopIteration
        result = toolbox.run_command(
            argv,
            command_id=command_id or None,
            timeout=timeout,
            mutate=mutate,
            execute=True,
            capture_full=True,
        )
    except StopIteration:
        pass
    except PolicyError as exc:  # e.g. a denied path inside an allowed command
        result = {
            "command": " ".join(argv),
            "cwd": str(toolbox.workdir),
            "returncode": -2,
            "stdout_tail": "",
            "stderr_tail": f"command rejected by the access policy: {exc}",
        }
    except subprocess.TimeoutExpired as exc:
        stdout = exc.stdout or ""
        stderr = exc.stderr or ""
        stdout_full = tools.filter_output(stdout) if isinstance(stdout, str) else ""
        stderr_full = tools.filter_output(stderr) if isinstance(stderr, str) else ""
        timeout_message = f"command timed out after {timeout}s"
        result = {
            "command": " ".join(argv),
            "cwd": str(toolbox.workdir),
            "returncode": -9,
            "stdout_tail": stdout_full[-2000:],
            "stderr_tail": (stderr_full + "\n" + timeout_message).strip()[-2000:],
            "timed_out": True,
            "_stdout_full": stdout_full,
            "_stderr_full": (stderr_full + "\n" + timeout_message).strip(),
        }
    except OSError as exc:
        result = {
            "command": " ".join(argv),
            "cwd": str(toolbox.workdir),
            "returncode": -1,
            "stdout_tail": "",
            "stderr_tail": f"command could not start: {exc}",
        }
    result["rung"] = rung
    stdout_full = str(result.pop("_stdout_full", result.get("stdout_tail", "")) or "")
    stderr_full = str(result.pop("_stderr_full", result.get("stderr_tail", "")) or "")
    if result.get("returncode") is not None:
        # Keep complete output outside graph state.  The immutable artifact and
        # bounded state tails together provide both replayability and compact
        # checkpoints.  One combined file preserves stdout/stderr attribution.
        artifact_stage = log_stage or ("cost" if rung == "cost" else "validation")
        artifacts = stage_services._artifacts_for_stage(state, artifact_stage)
        command_index = sum(
            1
            for item in artifacts.manifest.get("artifacts", [])
            if item.get("kind") == "command_log" and item.get("rung") == rung
        )
        directory = _LOG_DIRS.get(artifact_stage, f"{artifact_stage}/logs")
        relative = f"{directory}/{rung}_{command_index:03d}.log"
        log_text = (
            f"command: {result.get('command', '')}\n"
            f"command_id: {command_id}\n"
            f"cwd: {result.get('cwd', '')}\n"
            f"returncode: {result.get('returncode')}\n"
            f"timed_out: {bool(result.get('timed_out', False))}\n\n"
            "=== STDOUT ===\n" + stdout_full + "\n\n=== STDERR ===\n" + stderr_full
        )
        ref = artifacts.write_text(
            artifact_stage,
            relative,
            log_text,
            kind="command_log",
            status="passed" if result.get("returncode") == 0 else "failed",
            metadata={"rung": rung, "command": str(result.get("command", ""))[:500]},
        )
        result["log_path"] = ref["path"]
        result["full_log_path"] = ref["path"]
        result["command_id"] = command_id
        result["stdout_truncated"] = len(stdout_full) > len(str(result.get("stdout_tail", "")))
        result["stderr_truncated"] = len(stderr_full) > len(str(result.get("stderr_tail", "")))
        observation = observations.build_failure_observation(
            rung,
            result,
            stdout=stdout_full,
            stderr=stderr_full,
            log_path=ref["path"],
            workdir=str(toolbox.workdir),
        )
        if observation:
            result["failure_observation"] = observation
    return result
